---
func trailReportFor(summary reviewtypes.RunSummary, aggregateOutput string) (TrailReport, bool) {
	if verdict := strings.TrimSpace(aggregateOutput); verdict != "" {
		prose, comments, ok := splitTrailJSON(verdict)
		if prose == "" {
			prose = verdict
		}
		if !ok || (len(comments) == 0 && proseReportsFindings(prose)) {
			return TrailReport{Prose: prose}, true
		}
		return TrailReport{Comments: comments}, len(comments) > 0
	}
	var merged []TrailComment
	for _, run := range usableAgentRuns(summary) {
		prose, comments, ok := splitTrailJSON(joinAssistantText(run.Buffer))
		if !ok || (len(comments) == 0 && proseReportsFindings(prose)) {
			return TrailReport{Prose: combinedReviewNarratives(summary)}, true
		}
		merged = append(merged, comments...)
	}
	return TrailReport{Comments: merged}, len(merged) > 0
}
--- maybePostReviewToTrail
func maybePostReviewToTrail(
	ctx context.Context,
	out io.Writer,
	deps Deps,
	outputMode, profileName string,
	summary reviewtypes.RunSummary,
	aggregateOutput string,
) {
	if outputMode != ReviewOutputTrail || summary.Cancelled {
		return
	}
	report, post := trailReportFor(summary, aggregateOutput)
	if !post {
		fmt.Fprintln(out, "Nothing to report, so nothing was posted to the trail.")
		return
	}
	if deps.PostReviewToTrail == nil {
		fmt.Fprintln(out, "Trail output is not available here; the review was kept local.")
		return
	}
	// On success the hook prints its own confirmation and trail link.
	if err := deps.PostReviewToTrail(ctx, out, profileName, report); err != nil {
		if !userMessageAlreadyPrinted(err) {
			fmt.Fprintf(out, "Could not post the review to the trail: %v\n", err)
		}
	}
}

